/**
 * Human-readable MITRE CWE names, bundled as a JSON map (generated by scripts/gen_cwe_names.py).
 * The map is a lazy chunk: it is fetched on the first lookup and cached for the session.
 */
type CweNames = Record<string, string>;

const CWE_ID_RE = /^CWE-(\d{1,6})$/;

let names: Promise<CweNames> | null = null;

function loadNames(): Promise<CweNames> {
  names ??= import("../data/cwe-names.json").then((mod) => mod.default as CweNames);
  return names;
}

/** `CWE-79` -> "Improper Neutralization of ..."; other ids (NVD-CWE-Other, unknown numbers) -> null. */
export async function cweName(id: string): Promise<string | null> {
  const m = CWE_ID_RE.exec(id);
  if (!m) return null;
  const key = String(Number(m[1]));
  try {
    const map = await loadNames();
    return Object.hasOwn(map, key) ? map[key] : null;
  } catch {
    // The chunk failed to load: forget the rejected promise so a later lookup can retry.
    names = null;
    return null;
  }
}
